1	//! Which props of a component evidence puts forward (ADR 0028, section A).
2	//!
3	//! [`decide`] is the one place the rules are combined: it takes the [`Evidence`] each lane gathers for the members a
4	//! component's props type reaches and says, for each member, whether it is a typed row, a name in its collapsed
5	//! layer's `used` list, left in that layer, or decided as today because the body says nothing. It is pure and total:
6	//! no I/O, no name lists, and its output follows the order of the members it is given.
7	//!
8	//! Both lanes reach it through [`annotate`] (ADR 0028, slice T7): the structural resolver after it resolves a
9	//! component, the checker's merges after they replace its props. The inputs are the same for both: the
10	//! lane-independent [`Inputs`] gathered once by the resolver, and the members the entry's props and layers reach
11	//! ([`props_type::members`]). Story `args` are absent evidence: stories files are not discovered.
12	
13	pub(crate) mod call_sites;
14	pub(crate) mod forwarding;
15	pub(crate) mod props_type;
16	
17	use std::collections::{BTreeMap, BTreeSet};
18	
19	use crate::types::output::{ComponentEntry, Relevance};
20	
21	/// The evidence about one component that does not depend on the lane, gathered once by the structural resolver.
22	#[derive(Debug, Clone, Default, PartialEq, Eq)]
23	pub(crate) struct Inputs {
24	    /// What the props type writes itself.
25	    pub(crate) props_type: props_type::PropsType,
26	    /// What the component's body does with its props; `None` when it has no function of its own.
27	    pub(crate) body: Option<Body>,
28	    /// The props consumers pass at its JSX call sites.
29	    pub(crate) call_sites: CallSites,
30	}
31	
32	/// Decides where each member of `entry`'s props goes, from its [`Inputs`] and the members its listed props and layers
33	/// reach, and writes [`ComponentEntry::relevance`]. Every lane calls it after it last changes the props or layers, so
34	/// the decision is one function of the same inputs. Without inputs the relevance is empty: unknown, never guessed.
35	pub(crate) fn annotate(entry: &mut ComponentEntry) {
36	    let Some(inputs) = entry.relevance_evidence.0.clone() else {
37	        entry.relevance.clear();
38	        return;
39	    };
40	    let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
41	    let members = props_type::members(&inputs.props_type, rows, &entry.inheritance, crate::types::ambient::is_dom_file);
42	    let evidence =
43	        Evidence { members, body: inputs.body.clone(), call_sites: inputs.call_sites.clone(), story_args: Vec::new() };
44	    let listed = |name: &str| entry.props.contains_key(name) || entry.notable_inherited.contains_key(name);
45	    entry.relevance = relevance_of(&decide(&evidence), listed);
46	}
47	
48	/// The relevance of each listed name, and of each unlisted one evidence puts forward.
49	fn relevance_of(shown: &Shown, listed: impl Fn(&str) -> bool) -> BTreeMap<String, Relevance> {
50	    let lists = [
51	        (&shown.rows, Relevance::Row),
52	        (&shown.used, Relevance::Used),
53	        (&shown.collapsed, Relevance::Collapsed),
54	        (&shown.as_today, Relevance::AsToday),
55	    ];
56	    let mut relevance = BTreeMap::new();
57	    for (names, placed) in lists {
58	        let forward = matches!(placed, Relevance::Row | Relevance::Used);
59	        for name in names.iter().filter(|name| forward || listed(name)) {
60	            relevance.entry(name.clone()).or_insert(placed);
61	        }
62	    }
63	    relevance
64	}
65	
66	/// Everything known about the members one component's props type reaches.
67	#[derive(Debug, Clone, Default, PartialEq, Eq)]
68	pub(crate) struct Evidence {
69	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
70	    /// once, by its first member.
71	    pub(crate) members: Vec<Member>,
72	    /// What the component's own function body does with its props; `None` when it has no function of its own.
73	    pub(crate) body: Option<Body>,
74	    /// The props passed at the component's JSX call sites across the project.
75	    pub(crate) call_sites: CallSites,
76	    /// The names set in the `args` of the component's stories. Any one of them counts: stories have no floor.
77	    pub(crate) story_args: Vec<String>,
78	}
79	
80	/// One member the props type reaches, with the signals its declaration gives.
81	#[derive(Debug, Clone, Default, PartialEq, Eq)]
82	pub(crate) struct Member {
83	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
84	    pub(crate) name: String,
85	    /// The props type declares it itself, not through an inherited source.
86	    pub(crate) own: bool,
87	    /// A key a `Pick<X, …>` names.
88	    pub(crate) picked: bool,
89	    /// It redeclares or narrows a base member.
90	    pub(crate) overrides: bool,
91	    /// It is not optional.
92	    pub(crate) required: bool,
93	    /// Its declaration carries a `@default` tag.
94	    pub(crate) default_tag: bool,
95	    /// It carries a JSDoc comment: orders the rows, never shows a member.
96	    pub(crate) documented: bool,
97	    /// Its type is a union of literals: orders the rows, never shows a member.
98	    pub(crate) literal_union: bool,
99	    /// Declared by `@types/react`, or reaching the component only through a spread onto a DOM tag. Computed by the
100	    /// lane from the declaring path, never from the name.
101	    pub(crate) ambient: bool,
102	}
103	
104	/// What a component's function body does with its props, read from the syntax alone.
105	#[derive(Debug, Clone, Default, PartialEq, Eq)]
106	pub(crate) struct Body {
107	    /// The props the body reads. Complete only when `handed_on` is false.
108	    pub(crate) reads: Vec<String>,
109	    /// The props destructured with a default value.
110	    pub(crate) defaulted: Vec<String>,
111	    /// The JSX elements the body writes, in source order.
112	    pub(crate) elements: Vec<Element>,
113	    /// The props object or a rest binding escapes in a way the syntax cannot follow: what the body says still holds,
114	    /// but its silence about a prop is unknown, never guessed.
115	    pub(crate) handed_on: bool,
116	}
117	
118	/// One JSX element a component body writes.
119	#[derive(Debug, Clone, PartialEq, Eq)]
120	pub(crate) struct Element {
121	    /// What the tag resolves to.
122	    pub(crate) target: Target,
123	    /// Its attributes in source order, so a named attribute's place before or after a spread is kept.
124	    pub(crate) attributes: Vec<Attribute>,
125	}
126	
127	/// What a JSX tag resolves to.
128	#[derive(Debug, Clone, PartialEq, Eq)]
129	pub(crate) enum Target {
130	    /// A host element: a spread onto it passes only ambient DOM attributes.
131	    Dom,
132	    /// A component resolved by symbol and import, with the names of its own non-ambient props.
133	    Component(Vec<String>),
134	    /// A component tag that did not resolve: a spread onto it leaves the body's evidence unknown.
135	    Unresolved,
136	}
137	
138	/// One attribute of a JSX element.
139	#[derive(Debug, Clone, PartialEq, Eq)]
140	pub(crate) enum Attribute {
141	    /// `name={value}`, with the component's own prop the value is, when it is exactly one.
142	    Named {
143	        /// The attribute's name.
144	        name: String,
145	        /// The component's prop the value is, if it is exactly one. Kept from the extractor's facts; [`decide`] gives
146	        /// it no weight (an attribute valued with an own prop adds nothing).
147	        prop: Option<String>,
148	    },
149	    /// `{...value}`.
150	    Spread(SpreadOf),
151	}
152	
153	/// What a JSX spread attribute spreads.
154	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
155	pub(crate) enum SpreadOf {
156	    /// The props object, whole.
157	    Props,
158	    /// A rest binding of the props object.
159	    Rest,
160	    /// Any other expression: no evidence about the props.
161	    Other,
162	}
163	
164	/// How often each prop is passed at a component's JSX call sites.
165	#[derive(Debug, Clone, Default, PartialEq, Eq)]
166	pub(crate) struct CallSites {
167	    /// The number of call sites.
168	    pub(crate) sites: u32,
169	    /// Each prop passed at them, with the number of sites passing it.
170	    pub(crate) passed: Vec<(String, u32)>,
171	}
172	
173	impl CallSites {
174	    /// Whether `count` of the sites reach the floor of `max(2, 20%)` of them.
175	    fn at_floor(&self, count: u32) -> bool {
176	        count >= 2 && u64::from(count) * 5 >= u64::from(self.sites)
177	    }
178	}
179	
180	/// Where [`decide`] puts each member, every list in the order of [`Evidence::members`], except that `rows` puts the
181	/// documented and literal-union members first.
182	#[derive(Debug, Clone, Default, PartialEq, Eq)]
183	pub(crate) struct Shown {
184	    /// Typed rows.
185	    pub(crate) rows: Vec<String>,
186	    /// Ambient members named in their collapsed layer's `used` list.
187	    pub(crate) used: Vec<String>,
188	    /// Members left in their collapsed layer.
189	    pub(crate) collapsed: Vec<String>,
190	    /// Members with no signal whose body evidence is incomplete: listed or collapsed as today, so missing evidence
191	    /// never hides more than today does.
192	    pub(crate) as_today: Vec<String>,
193	}
194	
195	/// Decides, from the evidence alone, where each member of a component's props goes.
196	pub(crate) fn decide(evidence: &Evidence) -> Shown {
197	    let body = evidence.body.as_ref();
198	    let complete = body.is_some_and(Body::is_complete);
199	    let facts = |names: fn(&Body) -> &[String]| -> BTreeSet<&str> {
200	        body.map(|body| names(body).iter().map(String::as_str).collect()).unwrap_or_default()
201	    };
202	    let (reads, defaulted) = (facts(|body| &body.reads), facts(|body| &body.defaulted));
203	    let forwarded = body.map(Body::forwarded).unwrap_or_default();
204	    let passed: BTreeSet<&str> = evidence
205	        .call_sites
206	        .passed
207	        .iter()
208	        .filter(|(_, count)| evidence.call_sites.at_floor(*count))
209	        .map(|(name, _)| name.as_str())
210	        .chain(evidence.story_args.iter().map(String::as_str))
211	        .collect();
212	    let mut shown = Shown::default();
213	    let mut ordered_rows = Vec::new();
214	    let mut placed = BTreeSet::new();
215	    for member in &evidence.members {
216	        let name = member.name.as_str();
217	        if !placed.insert(name) {
218	            continue;
219	        }
220	        let read = reads.contains(name);
221	        let defaulted = member.default_tag || defaulted.contains(name);
222	        let declared = member.own || member.picked || member.overrides || member.required || defaulted;
223	        let list = if declared || passed.contains(name) || (!member.ambient && (read || forwarded.contains(name))) {
224	            ordered_rows.push((!(member.documented || member.literal_union), member.name.clone()));
225	            continue;
226	        } else if member.ambient && read {
227	            &mut shown.used
228	        } else if !complete {
229	            &mut shown.as_today
230	        } else {
231	            &mut shown.collapsed
232	        };
233	        list.push(member.name.clone());
234	    }
235	    ordered_rows.sort_by_key(|(plain, _)| *plain);
236	    shown.rows = ordered_rows.into_iter().map(|(_, name)| name).collect();
237	    shown
238	}
239	
240	impl Body {
241	    /// Whether the body's evidence is complete, so that a prop it never mentions is known to be unused: nothing handed
242	    /// on, and no spread of the props onto a tag that did not resolve. What an incomplete body does say (a read, a
243	    /// default, a forward) is still certain; only its silence is unknown.
244	    fn is_complete(&self) -> bool {
245	        !self.handed_on
246	            && !self.elements.iter().any(|element| {
247	                element.target == Target::Unresolved
248	                    && element.attributes.iter().any(|attribute| attribute.spreads_props())
249	            })
250	    }
251	
252	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
253	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
254	    fn forwarded(&self) -> BTreeSet<&str> {
255	        let mut forwarded = BTreeSet::new();
256	        for element in &self.elements {
257	            let Target::Component(own) = &element.target else { continue };
258	            for (at, attribute) in element.attributes.iter().enumerate() {
259	                if !attribute.spreads_props() {
260	                    continue;
261	                }
262	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
263	                    .iter()
264	                    .filter_map(|after| match after {
265	                        Attribute::Named { name, .. } => Some(name.as_str()),
266	                        Attribute::Spread(_) => None,
267	                    })
268	                    .collect();
269	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
270	            }
271	        }
272	        forwarded
273	    }
274	}
275	
276	impl Attribute {
277	    /// Whether the attribute spreads the props object or a rest binding of it.
278	    fn spreads_props(&self) -> bool {
279	        matches!(self, Self::Spread(SpreadOf::Props | SpreadOf::Rest))
280	    }
281	}
