502	    fn an_unknown_body_is_never_guessed() {
503	        let said = || Body { defaulted: strings(&["e"]), ..reading(&["a"]) };
504	        let handed_on = Body { handed_on: true, ..said() };
505	        let unresolved =
506	            Body { elements: vec![element(Target::Unresolved, vec![Attribute::Spread(SpreadOf::Rest)])], ..said() };
507	        let members = || {
508	            vec![
509	                inherited("a"),
510	                inherited("b"),
511	                ambient("c"),
512	                Member { required: true, ..inherited("d") },
513	                inherited("e"),
514	            ]
515	        };
516	        // What an incomplete body says still holds; only its silence is unknown, ambient or not.
517	        let incomplete: &[(&str, Placed)] = &[
518	            ("a", Placed::Row),
519	            ("b", Placed::AsToday),
520	            ("c", Placed::AsToday),
521	            ("d", Placed::Row),
522	            ("e", Placed::Row),
523	        ];
524	        let none: &[(&str, Placed)] = &[
525	            ("a", Placed::AsToday),
526	            ("b", Placed::AsToday),
527	            ("c", Placed::AsToday),
528	            ("d", Placed::Row),
529	            ("e", Placed::AsToday),
530	        ];
531	        table(vec![
532	            ("handed on", with(members(), Some(handed_on)), incomplete),
533	            ("spread onto an unresolved tag", with(members(), Some(unresolved)), incomplete),
534	            ("no function of its own", with(members(), None), none),
535	        ]);
536	    }
537	
538	    #[test]
539	    fn names_carry_no_meaning_and_order_follows_the_members() {
540	        let evidence = |names: [&str; 4]| {
541	            with(
542	                vec![inherited(names[0]), ambient(names[1]), inherited(names[2]), ambient(names[3])],
543	                Some(reading(&[names[2], names[3]])),
544	            )
545	        };
546	        let plain = decide(&evidence(["a", "b", "c", "d"]));
547	        let familiar = decide(&evidence(["className", "style", "onClick", "children"]));
548	        assert_eq!((plain.rows, plain.used, plain.collapsed), (strings(&["c"]), strings(&["d"]), strings(&["a", "b"])));
549	        assert_eq!(familiar.rows, ["onClick"]);
550	        assert_eq!(familiar.used, ["children"]);
551	        assert_eq!(familiar.collapsed, ["className", "style"]);
