444	impl Revision {
445	    /// Discover, parse, merge, resolve and assemble every source file.
446	    pub(crate) fn cold(options: &PipelineOptions, id: u64) -> Revision {
447	        let mut revision = Revision::resolve_cold(options, id, None);
448	        let (output, keys) = revision
449	            .assemble(options, |id| revision.resolved.get(id).map(|r| (r.entry.clone(), r.diagnostics.clone())));
450	        revision.output = Arc::new(output);
451	        revision.keys = keys;
452	        revision
453	    }
454	
455	    /// The output of a cold run that is never updated, so each entry moves into it instead of being copied.
456	    pub(crate) fn cold_output(options: &PipelineOptions) -> ExtractionOutput {
457	        Revision::cold_output_early(options, None)
458	    }
459	
460	    /// [`Revision::cold_output`], handing `on_roots` the checker program's root files as the parse has them, as soon as
461	    /// the project is parsed and merged and before the rest of the pass ([`predicted_root_files`]).
462	    pub(crate) fn cold_output_early(
463	        options: &PipelineOptions,
464	        on_roots: Option<Box<dyn FnOnce(Vec<Utf8PathBuf>) + '_>>,
465	    ) -> ExtractionOutput {
466	        let mut revision = Revision::resolve_cold(options, 0, on_roots);
467	        let mut resolved = std::mem::take(&mut revision.resolved);
468	        let (output, _) = revision.assemble(options, |id| resolved.remove(id).map(Resolved::into_parts));
469	        free_in_background(revision);
470	        output
471	    }
472	
473	    /// Everything [`Revision::cold`] does except assembling the output.
474	    fn resolve_cold(
475	        options: &PipelineOptions,
476	        id: u64,
477	        on_roots: Option<Box<dyn FnOnce(Vec<Utf8PathBuf>) + '_>>,
478	    ) -> Revision {
479	        let Indexed {
480	            start,
481	            cache,
482	            src_files,
483	            global,
484	            head_diagnostics,
485	            file_diagnostics,
486	            mut lib_diagnostics,
487	            react_types,
488	            file_demands,
489	        } = Indexed::build(options);
490	        if let Some(on_roots) = on_roots {
491	            on_roots(predicted_root_files(&global, options));
492	        }
493	        let demands: Vec<Demand> = file_demands.into_iter().flat_map(|(_, demands)| demands).collect();
494	
495	        let dependencies = options.load_dependencies.then(|| Arc::new(dependency_types::load(demands, options, None)));
